async ({ session: { outline, inspectEntry } }) => {
  const o: any = await outline({ previewChars: 600 });
  const entries = o.entries ?? [];
  const byState: Record<string, number> = {};
  for (const e of entries) byState[e.state] = (byState[e.state] ?? 0) + 1;
  const collapsed = entries.filter((e: any) => String(e.preview).includes("[Pit: collapsed"));
  let original: any = null;
  const m = collapsed[0] && String(collapsed[0].preview).match(/inspectEntry\("(\d+)"\)/g);
  if (m) {
    const ids = m.map((s: string) => s.match(/\d+/)![0]);
    const r: any = await inspectEntry(ids[ids.length - 1], { limit: 5 });
    original = { id: ids.at(-1), keys: Object.keys(r), text: String(r.original?.text ?? "").slice(0, 300) };
  }
  return {
    estimatedTokens: o.estimatedTokens, count: entries.length, byState,
    collapsed: collapsed.map((e: any) => ({ id: e.id, state: e.state, tokens: e.tokens, preview: String(e.preview).slice(-420) })),
    original,
    tail: entries.slice(-8).map((e: any) => `${e.id}:${e.role}:${e.tokens}:${e.state}`),
  };
}
